*{box-sizing:border-box} :root{--ink:#ece7d9;--muted:#88877c;--paper:#171c18;--panel:#20251f;--line:#33382e;--gold:#d5a65d;--rust:#bb6849;--green:#a6a879;--mono:'DM Mono',monospace;--sans:'DM Sans',sans-serif;--display:'Rye',serif}html{background:#121612;color:var(--ink);font-family:var(--sans);min-height:100%;}body{margin:0;min-height:100vh;background:radial-gradient(ellipse at 42% 5%,#282c22 0,#171c18 54%,#121612 100%);}.game-shell{max-width:1450px;margin:0 auto;padding:0 40px}.topbar{height:68px;border-bottom:1px solid #33372e;display:flex;align-items:center;justify-content:space-between}.brand{color:#e7dfcb;text-decoration:none;letter-spacing:2.5px;font:13px var(--mono);display:flex;align-items:center;gap:10px}.brand i{font-style:normal;color:var(--gold)}.brand-star{font-size:21px;color:var(--gold)}.chapter{font:10px var(--mono);color:#89897d;letter-spacing:1.55px}.chapter-dot{display:inline-block;width:6px;height:6px;border-radius:50%;background:#c66c4f;margin-right:8px;box-shadow:0 0 9px #c66c4f}.chapter-slash{color:#d5a65d;margin:0 9px}.sound-toggle{background:none;border:0;color:#d4cbb9;display:flex;gap:8px;align-items:center;font:12px var(--mono);cursor:pointer}.sound-toggle span{font-size:9px;letter-spacing:1.2px;color:#908e80}.game-layout{display:grid;grid-template-columns:minmax(0,1fr) 325px;gap:24px;padding-top:26px;align-items:start}.battle-heading{height:70px;display:flex;justify-content:space-between;align-items:flex-start}.eyebrow{font:9px var(--mono);letter-spacing:2px;color:var(--gold)}h1{font:26px var(--display);font-weight:400;margin:6px 0;color:#f0e9d8;letter-spacing:.1px}h1 span{color:#a5a18e}.round-card{height:50px;min-width:76px;border-left:1px solid #4b493a;padding:3px 4px 0 17px;text-align:right}.round-card span{font:8px var(--mono);letter-spacing:1px;color:#8f8d7f;display:block}.round-card strong{font:22px var(--display);color:var(--gold);font-weight:400;line-height:1.45}.canvas-frame{position:relative;width:100%;aspect-ratio: 1.72;background:#5d5a43;overflow:hidden;border:1px solid #5b5140;box-shadow:0 14px 40px #0005,inset 0 0 0 5px #171a16}.canvas-frame canvas{display:block;width:100%;height:100%;cursor:crosshair;image-rendering:auto}.canvas-vignette{pointer-events:none;position:absolute;inset:0;box-shadow:inset 0 0 50px #171a1670,inset 0 0 0 5px #171a16}.map-label{position:absolute;font:8px var(--mono);letter-spacing:1.4px;color:#e5d8bd;background:#1a1d17cc;border:1px solid #93866955;padding:7px 10px}.map-label-top{top:14px;left:15px}.map-pin{color:#e1b06a;margin-right:5px}.map-coords{position:absolute;right:14px;bottom:13px;font:8px var(--mono);letter-spacing:1.1px;color:#ede2c2aa}.canvas-toast{position:absolute;top:17%;left:50%;transform:translate(-50%,-10px);padding:10px 15px;background:#1b201de8;border:1px solid #d5a65d70;color:#f2dfb6;font:11px var(--mono);letter-spacing:.5px;opacity:0;transition:.24s;pointer-events:none;white-space:nowrap;z-index:4}.canvas-toast.show{opacity:1;transform:translate(-50%,0)}.battle-footer{height:67px;border-bottom:1px solid #35382e;display:flex;justify-content:space-between;align-items:center}.objective{display:flex;gap:11px;align-items:center}.objective-icon{font-size:22px;color:var(--gold)}.objective b,.objective span:last-child{display:block}.objective b{font:9px var(--mono);letter-spacing:1px;color:#dcd4c2}.objective div>span{font-size:10px;color:#898b7d;margin-top:3px}.turn-actions{display:flex;align-items:center;gap:17px}.ap-label{font:8px var(--mono);letter-spacing:1px;color:#9e9c8b}.ap-label b{color:#f3e5c4;font-size:15px;margin-left:5px}.end-turn-button,.primary-button{background:#bb714a;border:1px solid #d08b5b;color:#fff4df;font:10px var(--mono);letter-spacing:1px;padding:12px 14px;cursor:pointer;transition:.2s}.end-turn-button:hover,.primary-button:hover{background:#d18555;transform:translateY(-1px)}.end-turn-button span,.primary-button span{font-size:15px;padding-left:9px}.sidebar{display:flex;flex-direction:column;gap:13px}.panel{background:linear-gradient(145deg,#22271f,#1c211c);border:1px solid #34392f;padding:14px 15px}.panel-title{display:flex;align-items:center;justify-content:space-between;font:9px var(--mono);letter-spacing:1.5px;color:#c3bda9;margin-bottom:12px}.live-tag{font-size:8px;letter-spacing:1px;color:#a6b084}.live-tag i,.status-pip,.log-dot{width:5px;height:5px;border-radius:50%;display:inline-block;background:#a4b181;box-shadow:0 0 6px #9ca674;margin-right:5px}.unit-card{display:flex;gap:11px;align-items:center}.unit-avatar{position:relative;flex:0 0 48px;height:48px;display:flex;align-items:center;justify-content:center;overflow:hidden}.cowboy-avatar{background:linear-gradient(140deg,#514535,#302d27);border:1px solid #6c5940}.cowboy-avatar span{font-size:30px;color:#d9b677;transform:rotate(180deg);text-shadow:0 2px #492c21}.cowboy-avatar b{position:absolute;bottom:3px;font:7px var(--mono);letter-spacing:1px;color:#fff0d6;background:#24251eaa;padding:2px 4px}.unit-info{min-width:0;flex:1}.unit-name{font-size:11px;font-weight:700;color:#e8e1d1;white-space:nowrap}.unit-role{font:7px var(--mono);letter-spacing:.7px;color:#d2a35c;border:1px solid #66563c;padding:2px 4px;margin-left:4px;vertical-align:1px}.unit-subtitle{font-size:9px;color:#8e8d80;margin-top:2px}.health-row{display:flex;align-items:center;gap:6px;margin-top:7px;font:7px var(--mono);color:#929183}.health-row b{font-size:8px;color:#c9c1ac;font-weight:400}.health-track{height:4px;background:#474138;flex:1}.health-track i{height:100%;width:100%;display:block;background:#c77958;transition:width .2s}.ammo-row{font:8px var(--mono);color:#d1c6af;margin-top:6px}.ammo-row>span:first-child{color:#d6aa63}.ammo-row b{font-size:10px;color:#f1ddac;margin-left:3px}.ammo-note{color:#7d7e72;font-size:7px}.squad-divider{display:flex;gap:8px;align-items:center;margin:14px 0 10px;color:#858476;font:7px var(--mono);letter-spacing:1.1px}.squad-divider i{height:1px;background:#393d32;flex:1}.dog-card{padding:7px 0;border-top:1px solid #31362c}.dog-avatar{height:39px;flex-basis:39px;border-radius:50%;border:1px solid #8a7959;position:relative;background:radial-gradient(circle at 54% 46%,#d1b782 0 17%,#765a3e 18% 44%,#3f4334 45% 100%)}.dog-avatar:before,.dog-avatar:after{content:'';position:absolute;width:12px;height:19px;background:#4b4030;top:1px;z-index:0;clip-path:polygon(35% 0,100% 12%,73% 100%,0 58%)}.dog-avatar:before{left:1px;transform:rotate(-25deg)}.dog-avatar:after{right:1px;transform:scaleX(-1) rotate(-25deg)}.dog-avatar span{z-index:1;position:relative;color:#2b2921;font-size:12px}.dog-avatar-two{filter:hue-rotate(15deg) brightness(1.13)}.dog-card .unit-name{font-size:10px}.dog-role{color:#9eaf86;border-color:#485540}.dog-desc{font-size:8px;color:#999889;margin-top:2px}.dog-status{display:flex;align-items:center;font:7px var(--mono);color:#a6b084;margin-top:5px}.dog-loyalty{color:#b37c66;margin-left:auto;font-size:6px;letter-spacing:.5px}.intel-panel{padding-bottom:10px}.report-icon{color:#b5945d;font-size:15px}.threat-line{display:flex;align-items:center;gap:10px}.threat-icon{font-size:23px;color:#c36e51}.threat-line>div:nth-child(2){flex:1}.threat-line>div:nth-child(2) span{display:block;font:7px var(--mono);letter-spacing:.8px;color:#999889}.threat-line>div:nth-child(2) b{font:18px var(--display);font-weight:400;color:#eadac0}.threat-meter{display:flex;gap:3px}.threat-meter i{width:7px;height:15px;border:1px solid #605146;background:#2c2b25}.threat-meter i.active{background:#c36c4f;border-color:#c36c4f;box-shadow:0 0 6px #c36c4f55}.intel-divider{height:1px;background:#353a30;margin:10px 0}.recent-log{height:37px;overflow:hidden;font-size:8px;color:#b9b5a5}.log-entry{display:flex;gap:8px;line-height:1.5}.log-time{font:7px var(--mono);color:#d2a35c;min-width:27px}.log-bottom{margin-top:7px;padding-top:7px;border-top:1px solid #353a30;font:7px var(--mono);letter-spacing:.8px;color:#828476}.log-dot{width:4px;height:4px}.controls-panel{padding-bottom:11px}.small-help{width:14px;height:14px;border:1px solid #555747;border-radius:50%;display:grid;place-items:center;font:9px var(--mono);color:#989687}.control-row{display:flex;align-items:center;gap:9px;margin:7px 0;font-size:8px;color:#b1b09f}.keycap{font:7px var(--mono);color:#ddcfb3;background:#30332b;border:1px solid #4c4a3b;min-width:43px;text-align:center;padding:4px 3px}.tip-box{display:flex;gap:8px;background:#2a2a20;border-left:2px solid #b69155;padding:8px 8px 7px;margin-top:10px}.tip-box>span{color:#e2b562}.tip-box p{font-size:8px;line-height:1.5;color:#a5a18f;margin:0}.tip-box b{font:7px var(--mono);letter-spacing:.6px;color:#d3bc8d}.sidebar-foot{text-align:center;color:#79796c;font:7px var(--mono);letter-spacing:1px;padding-top:1px}.sidebar-foot span{color:#be995c;margin-right:4px}.site-footer{display:flex;justify-content:space-between;padding:18px 0 20px;font:7px var(--mono);letter-spacing:1px;color:#66695d}.site-footer i{font-style:normal;color:#ac8c55;margin:0 3px}.intro-overlay,.upgrade-overlay,.gameover-overlay{position:absolute;inset:0;z-index:5;display:flex;align-items:center;justify-content:center;background:#111713b9;backdrop-filter:blur(2px)}.intro-card{width:min(380px,88%);padding:27px 32px 24px;text-align:center;background:linear-gradient(145deg,#262a22f5,#191d18f5);border:1px solid #85704e;box-shadow:0 12px 60px #0008;position:relative}.intro-card:before,.intro-card:after{content:'✦';position:absolute;color:#b28c52;font-size:10px;top:10px}.intro-card:before{left:11px}.intro-card:after{right:11px}.intro-mark{font-size:22px;color:#d1a459;margin-bottom:9px}.intro-card h2,.upgrade-panel h2{font:24px var(--display);font-weight:400;line-height:1.28;color:#f0e5cd;margin:10px 0}.intro-card p,.upgrade-panel>p{font-size:11px;line-height:1.65;color:#b1ad9e;margin:0 auto 18px;max-width:300px}.primary-button{padding:12px 18px}.intro-hint{margin-top:17px;font:7px var(--mono);letter-spacing:1.2px;color:#77796e}.hidden{display:none!important}.upgrade-overlay{background:#111713d9}.upgrade-panel{width:min(650px,92%);padding:25px;background:#20251ff5;border:1px solid #756348;box-shadow:0 16px 70px #000b}.upgrade-panel h2{margin:7px 0}.upgrade-panel h2 em{font-style:normal;color:#d5a65d}.upgrade-panel>p{margin:0 0 17px;max-width:none}.upgrade-options{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.upgrade-option{background:#292c23;border:1px solid #4c4939;padding:14px 12px;color:#e8e0cd;text-align:left;cursor:pointer;min-height:133px;transition:.2s}.upgrade-option:hover{border-color:#d0a45f;background:#323329;transform:translateY(-2px)}.upgrade-icon{font-size:22px;color:#d1a45e}.upgrade-option h3{font:11px var(--mono);letter-spacing:.4px;margin:8px 0 5px}.upgrade-option p{font-size:9px;line-height:1.5;color:#a8a696;margin:0}.upgrade-key{display:block;margin-top:10px;font:7px var(--mono);letter-spacing:.8px;color:#be995b}.gameover-card{padding:33px}.gameover-card h2{font-size:27px}.gameover-card p{margin-bottom:20px}
@media(max-width:1050px){.game-shell{padding:0 22px}.game-layout{grid-template-columns:minmax(0,1fr) 285px;gap:15px}.panel{padding-left:12px;padding-right:12px}.game-layout{padding-top:20px}.canvas-frame{aspect-ratio:1.55}.ammo-note{font-size:6px}}
@media(max-width:780px){.game-shell{padding:0 14px}.topbar{height:54px}.chapter{font-size:8px;letter-spacing:.7px}.game-layout{grid-template-columns:1fr;gap:12px;padding-top:16px}.battle-heading{height:63px}.battle-heading h1{font-size:22px}.canvas-frame{aspect-ratio:1.28}.sidebar{display:grid;grid-template-columns:1fr 1fr;align-items:start;gap:9px}.squad-panel{grid-row:span 2}.panel{padding:11px}.site-footer{font-size:6px}.canvas-label{font-size:7px}.upgrade-panel{padding:18px}.upgrade-options{gap:6px}.upgrade-option{padding:10px 8px;min-height:138px}.upgrade-option h3{font-size:9px}.upgrade-option p{font-size:8px}.objective div>span{font-size:9px}}
@media(max-width:520px){.game-shell{padding:0 10px}.chapter{display:none}.brand{font-size:11px}.battle-heading{height:59px}.battle-heading h1{font-size:20px}.eyebrow{font-size:8px}.round-card{min-width:62px;padding-left:10px}.canvas-frame{aspect-ratio:1.05}.map-label-top{top:9px;left:9px;padding:5px 7px;font-size:7px}.map-coords{font-size:6px;right:9px;bottom:9px}.battle-footer{height:auto;min-height:62px;gap:6px}.objective{gap:6px}.objective-icon{font-size:17px}.objective b{font-size:8px}.objective div>span{max-width:110px;line-height:1.3}.turn-actions{gap:7px}.ap-label{font-size:7px}.end-turn-button{font-size:8px;padding:10px 7px}.end-turn-button span{padding-left:3px}.sidebar{grid-template-columns:1fr 1fr}.squad-panel{grid-column:span 2;grid-row:auto}.squad-panel .dog-card{display:inline-flex;width:49%;vertical-align:top}.squad-panel .dog-card:last-child{margin-left:1%}.squad-panel .unit-avatar{flex-basis:34px;height:34px}.dog-loyalty{font-size:5px}.dog-status{font-size:6px}.controls-panel{grid-column:span 2}.control-row{font-size:8px}.tip-box p{font-size:8px}.site-footer{gap:8px;line-height:1.5}.site-footer span:last-child{text-align:right}.intro-card{padding:22px 18px}.intro-card h2{font-size:22px}.intro-card p{font-size:10px}.upgrade-panel h2{font-size:18px}.upgrade-options{grid-template-columns:1fr}.upgrade-option{min-height:0;display:grid;grid-template-columns:30px 1fr;column-gap:5px;padding:9px}.upgrade-icon{grid-row:span 3;font-size:20px}.upgrade-option h3{margin:0 0 3px}.upgrade-option p{font-size:8px}.upgrade-key{display:none}}

(() => {
  const canvas = document.getElementById('gameCanvas');
  const ctx = canvas.getContext('2d');
  const cols = 22, rows = 14;
  const state = { started:false, gameOver:false, choosing:false, round:1, ap:2, ammo:6, maxAmmo:6, maxHp:6, hp:6, damage:2, range:5, move:4, dogDamage:1, dogHeal:0, armor:0, zombies:[], dogs:[{name:'Ranger',x:9,y:9,kind:'tracker'},{name:'Belle',x:11,y:8,kind:'guard'}], player:{x:10,y:8}, decor:[], blocked:new Set(), logs:[], selected:null, sound:true, seed:19321, toastTimer:null };
  const upgrades = [
    {icon:'✦',title:'Scharfschützenauge',text:'+1 Schaden für Clays Revolver. Ein sauberer Schuss zählt.',key:'CLAY'},
    {icon:'◈',title:'Schnelllader',text:'+2 Patronen und +1 maximale Munition.',key:'CLAY'},
    {icon:'♥',title:'Hart wie Leder',text:'+2 maximale Lebenspunkte und heilt Clay vollständig.',key:'CLAY'},
    {icon:'⌁',title:'Bluthund-Instinkt',text:'Ranger und Belle teilen +1 Schaden aus.',key:'HUNDE'},
    {icon:'➶',title:'Lange Schritte',text:'Clay kann sich 2 Felder weiter bewegen.',key:'CLAY'},
    {icon:'✚',title:'Belle hält Wache',text:'Belle heilt Clay am Ende jeder Runde um 1 Leben.',key:'BELLE'},
    {icon:'◎',title:'Ruhige Hand',text:'Clays Revolver hat 2 Felder mehr Reichweite.',key:'CLAY'},
    {icon:'⬟',title:'Dicker Mantel',text:'Clay erleidet 1 Schaden weniger pro Zombie-Angriff.',key:'CLAY'}
  ];
  function rnd(){state.seed=(state.seed*1664525+1013904223)>>>0;return state.seed/4294967296}
  const key=(x,y)=>`${x},${y}`;
  function setBlocked(){state.blocked.clear();[[2,1,5,3],[15,1,5,4],[1,10,5,3],[16,10,4,3]].forEach(([x,y,w,h])=>{for(let a=x;a<x+w;a++)for(let b=y;b<y+h;b++)state.blocked.add(key(a,b));});[[7,2],[8,2],[13,2],[14,2],[7,11],[8,11],[13,11],[14,11],[0,5],[21,9],[5,5],[17,8]].forEach(([x,y])=>state.blocked.add(key(x,y)));}
  function fit(){const r=canvas.getBoundingClientRect(),d=Math.min(window.devicePixelRatio||1,2);canvas.width=Math.round(r.width*d);canvas.height=Math.round(r.height*d);ctx.setTransform(d,0,0,d,0,0);draw();}
  function dims(){const r=canvas.getBoundingClientRect();return {w:r.width,h:r.height,tw:r.width/cols,th:r.height/rows}}
  function log(text){const box=document.getElementById('battleLog');const now=String(new Date().getMinutes()).padStart(2,'0')+':'+String(new Date().getSeconds()).padStart(2,'0');state.logs.unshift({text,time:now});state.logs=state.logs.slice(0,3);box.innerHTML=state.logs.map(v=>`<div class="log-entry"><span class="log-time">${v.time}</span><span>${v.text}</span></div>`).join('');}
  function toast(text){const el=document.getElementById('toast');el.textContent=text;el.classList.add('show');clearTimeout(state.toastTimer);state.toastTimer=setTimeout(()=>el.classList.remove('show'),1500)}
  function updateHud(){document.getElementById('roundNumber').textContent=String(state.round).padStart(2,'0');document.getElementById('apCount').textContent=state.ap;document.getElementById('ammoText').textContent=state.ammo;document.getElementById('clayHealthText').textContent=`${state.hp} / ${state.maxHp}`;document.getElementById('clayHealthBar').style.width=`${Math.max(0,state.hp/state.maxHp*100)}%`;document.getElementById('zombieCount').textContent=state.zombies.length;document.getElementById('objectiveText').textContent=state.zombies.length?`Noch ${state.zombies.length} Untote in Red Creek.`:'Räume die Untoten aus Red Creek.';const n=Math.min(5,state.zombies.length);document.querySelectorAll('#threatMeter i').forEach((el,i)=>el.classList.toggle('active',i<n));document.getElementById('endTurnButton').disabled=state.gameOver||state.choosing;document.getElementById('rangerStatus').textContent=state.dogs[0].hp===0?'Verletzt!':'Bei dir';document.getElementById('belleStatus').textContent=state.dogs[1].hp===0?'Verletzt!':'Bei dir';}
  function newZombies(){state.zombies=[];const count=Math.min(2+state.round,9);const places=[[0,2],[0,9],[21,3],[21,10],[4,0],[11,0],[19,0],[2,13],[10,13],[20,13],[0,6],[21,7]];let tries=0;while(state.zombies.length<count&&tries<100){tries++;let p=places[Math.floor(rnd()*places.length)],x=p[0],y=p[1];if(state.blocked.has(key(x,y))||state.zombies.some(z=>z.x===x&&z.y===y)||Math.abs(x-10)+Math.abs(y-8)<6)continue;state.zombies.push({x,y,hp:2+Math.floor((state.round-1)/3),maxHp:2+Math.floor((state.round-1)/3),id:Math.random(),flash:0});}}
  function begin(){state.started=true;document.getElementById('introOverlay').classList.add('hidden');newZombies();log('Die Glocke schlägt. Die Toten kommen.');updateHud();draw();}
  function draw(){if(!ctx)return;const {w,h,tw,th}=dims();ctx.clearRect(0,0,w,h);ctx.fillStyle='#777052';ctx.fillRect(0,0,w,h);
    // Dusty ground and main street
    for(let y=0;y<rows;y++)for(let x=0;x<cols;x++){let v=((x*29+y*17)%11);ctx.fillStyle=v<3?'#77704f':v<6?'#817755':'#797250';ctx.fillRect(x*tw,y*th,tw+.5,th+.5);if((x*13+y*7)%9===0){ctx.fillStyle='#b09c6d22';ctx.beginPath();ctx.ellipse((x+.4)*tw,(y+.35)*th,tw*.12,th*.05,-.3,0,Math.PI*2);ctx.fill();}}
    // Street, crossing the settlement
    for(let y=5;y<=8;y++)for(let x=0;x<cols;x++){ctx.fillStyle=(x+y)%2?'#9a8058':'#927a53';ctx.fillRect(x*tw,y*th,tw,th);if(y===6&&x%3===0){ctx.fillStyle='#d5bc8866';ctx.fillRect(x*tw+tw*.2,y*th+th*.83,tw*.4,1);}}
    // tiny paths to buildings
    for(const [x,y,ww,hh] of [[2,4,5,2],[15,5,5,1],[1,9,5,1],[16,9,4,1]]){ctx.fillStyle='#987e53';ctx.fillRect(x*tw,y*th,ww*tw,hh*th)}
    drawProps(tw,th);drawBuildings(tw,th);
    // tactical grid
    ctx.strokeStyle='#e3d3a015';ctx.lineWidth=1;for(let x=0;x<=cols;x++){ctx.beginPath();ctx.moveTo(x*tw,0);ctx.lineTo(x*tw,h);ctx.stroke()}for(let y=0;y<=rows;y++){ctx.beginPath();ctx.moveTo(0,y*th);ctx.lineTo(w,y*th);ctx.stroke()}
    drawHighlights(tw,th);state.zombies.forEach(z=>drawZombie(z,tw,th));state.dogs.forEach(d=>{if(d.hp!==0)drawDog(d,tw,th)});drawCowboy(state.player,tw,th);
    // dusk overlay
    const grad=ctx.createRadialGradient(w*.52,h*.5,h*.1,w*.52,h*.5,w*.8);grad.addColorStop(.55,'#1c1c1220');grad.addColorStop(1,'#11150f80');ctx.fillStyle=grad;ctx.fillRect(0,0,w,h);
  }
  function drawProps(tw,th){
    // Hitching rail, well, barrels and scrub
    for(const [x,y] of [[9,3],[12,3],[6,9],[15,9]]){ctx.fillStyle='#473a29';ctx.fillRect((x+.1)*tw,(y+.35)*th,tw*.8,th*.22);ctx.fillRect((x+.18)*tw,(y+.58)*th,tw*.09,th*.36);ctx.fillRect((x+.72)*tw,(y+.58)*th,tw*.09,th*.36);ctx.fillStyle='#ad8751';ctx.fillRect((x+.2)*tw,(y+.41)*th,tw*.6,th*.05)}
    // well
    ctx.fillStyle='#4b4534';ctx.beginPath();ctx.ellipse(12.1*tw,9.1*th,tw*.45,th*.28,0,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#b09665';ctx.lineWidth=2;ctx.stroke();ctx.fillStyle='#252b28';ctx.beginPath();ctx.ellipse(12.1*tw,9.1*th,tw*.29,th*.16,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#876d44';ctx.fillRect(11.9*tw,8.55*th,tw*.08,th*.65);
